require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../services/TicketService.php';Auth::requireLogin();if(!TicketService::canManage()){http_response_code(403);exit('دسترسی مدیریت تیکت‌ها برای شما فعال نیست.');}$filters=['status'=>trim((string)($_GET['status']??'')),'priority'=>trim((string)($_GET['priority']??'')),'category_id'=>(int)($_GET['category_id']??0)];$rows=TicketService::list($filters);$categories=TicketService::categories(false);$pageTitle='مدیریت تیکت‌ها';require __DIR__.'/../views/partials/admin-header.php';?>
<div class="section-heading-row"><div><h1>مدیریت تیکت‌ها</h1><p class="muted">صف مستقل رسیدگی به درخواست‌ها؛ بدون مدیریت در Inbox پیام‌رسان</p></div><div><a class="btn" href="/admin/ticket-categories.php">دسته‌بندی‌ها</a><a class="btn" href="/admin/ticket-settings.php">SLA و تنظیمات</a></div></div><form class="card filter-form"><label>وضعیت<select name="status"><option value="">همه</option><?php foreach(TicketService::STATUSES as $key=>$label):?><option value="<?=$key?>" <?=$filters['status']===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><label>اولویت<select name="priority"><option value="">همه</option><?php foreach(TicketService::PRIORITIES as $key=>$label):?><option value="<?=$key?>" <?=$filters['priority']===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><label>دسته<select name="category_id"><option value="">همه</option><?php foreach($categories as $category):?><option value="<?=$category['id']?>" <?=$filters['category_id']==$category['id']?'selected':''?>><?=e($category['title'])?></option><?php endforeach?></select></label><button class="btn">اعمال</button></form><section class="card"><div class="table-wrap"><table><thead><tr><th>شماره</th><th>عنوان / درخواست‌کننده</th><th>دسته</th><th>مسئول</th><th>اولویت</th><th>وضعیت</th><th>مهلت</th><th></th></tr></thead><tbody><?php foreach($rows as $ticket):?><tr><td><?=e($ticket['ticket_no'])?></td><td><strong><?=e($ticket['subject'])?></strong><small><?=e($ticket['requester_name'])?></small></td><td><?=e($ticket['category_title'])?></td><td><?=e($ticket['assignee_name']?:$ticket['unit_title']?:'—')?></td><td><?=e(TicketService::PRIORITIES[$ticket['priority']]??$ticket['priority'])?></td><td><span class="badge"><?=e(TicketService::STATUSES[$ticket['status']]??$ticket['status'])?></span></td><td><?=e($ticket['due_at']?format_jalali_datetime($ticket['due_at']):'—')?></td><td><a class="btn btn-small" href="/employee/ticket-view.php?id=<?=$ticket['id']?>">رسیدگی</a></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="8">تیکتی مطابق فیلتر پیدا نشد.</td></tr><?php endif?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
